export interface MiniMapProps {
  className?: string
  width?: number
  height?: number
  /** Fill per node: any CSS colour, or a custom property name like "--color-violet-500". */
  nodeColor?: (node: FlowNode) => string | undefined
}

/** Canvas minimap: redraws at most once per frame, outside React, whatever the node count. */
export function MiniMap({ className, width = 200, height = 140, nodeColor }: MiniMapProps) {
  const flow = useFlow()
  const ref = useRef<HTMLCanvasElement>(null)
  const colorRef = useRef(nodeColor)
  colorRef.current = nodeColor
  // Flow→minimap mapping from the last draw (minimap px = (flow - origin) * k); pointer handling inverts it.
  const map = useRef({ x0: 0, y0: 0, k: 1 })

  useLayoutEffect(() => {
    const canvas = ref.current!
    const ctx = canvas.getContext("2d")!
    let raf = 0
    let seen: unknown[] = []

    const draw = (force = false) => {
      raf = 0
      const s = flow.get()
      const deps = [s.nodes, s.sizes, s.handles, s.edges, s.viewport, s.size]
      if (!force && deps.every((d, i) => d === seen[i])) return
      seen = deps
      const dpr = devicePixelRatio || 1
      if (canvas.width !== width * dpr) (canvas.width = width * dpr), (canvas.height = height * dpr)

      const vp = s.viewport
      const view = { x: -vp.x / vp.zoom, y: -vp.y / vp.zoom, w: s.size.w / vp.zoom, h: s.size.h / vp.zoom }
      // Fit the graph, not graph ∪ viewport: panning away shouldn't shrink the map to specks.
      const b = s.nodeIds.length ? flow.bounds() : view
      const pad = 12
      const k = Math.min((width - pad * 2) / Math.max(b.w, 1), (height - pad * 2) / Math.max(b.h, 1))
      const m = (map.current = { x0: b.x + b.w / 2 - width / 2 / k, y0: b.y + b.h / 2 - height / 2 / k, k })

      // Let CSS resolve colours (var() fallbacks, color-mix, nested themes) into something canvas accepts.
      const css = getComputedStyle(canvas)
      const resolve = (c: string) => {
        canvas.style.color = c.startsWith("--") ? `var(${c}, var(--muted-foreground))` : c
        return css.color
      }
      const primary = resolve("--primary")
      ctx.setTransform(dpr * k, 0, 0, dpr * k, -m.x0 * dpr * k, -m.y0 * dpr * k)
      ctx.clearRect(m.x0, m.y0, width / k, height / k)

      // Edges first, as faint curves between ports.
      ctx.beginPath()
      for (const e of s.edges) {
        const a = s.nodes[e.source], t = s.nodes[e.target]
        if (!a || !t) continue
        const sb = s.handles[e.source]?.[e.sourceHandle] ?? guess("source", s.sizes[e.source])
        const tb = s.handles[e.target]?.[e.targetHandle] ?? guess("target", s.sizes[e.target])
        const p = { x: a.position.x + sb.x, y: a.position.y + sb.y }, q = { x: t.position.x + tb.x, y: t.position.y + tb.y }
        const { c1, c2 } = bezier(p, sb.side, q, tb.side)
        ctx.moveTo(p.x, p.y)
        ctx.bezierCurveTo(c1.x, c1.y, c2.x, c2.y, q.x, q.y)
      }
      ctx.strokeStyle = resolve(THEME.edge)
      ctx.lineWidth = 1.25 / k
      ctx.stroke()

      // Nodes, batched by colour: one path + fill per distinct colour.
      const groups = new Map<string, Path2D>()
      const selected = new Path2D()
      const r = 3 / k
      for (const id of s.nodeIds) {
        const n = s.nodes[id]
        const z = s.sizes[id] ?? DEFAULT_SIZE
        const c = colorRef.current?.(n) ?? "--muted-foreground"
        if (!groups.has(c)) groups.set(c, new Path2D())
        groups.get(c)!.roundRect(n.position.x, n.position.y, z.w, z.h, r)
        if (n.selected) selected.roundRect(n.position.x, n.position.y, z.w, z.h, r)
      }
      ctx.globalAlpha = colorRef.current ? 0.85 : 0.5
      for (const [c, path] of groups) {
        ctx.fillStyle = resolve(c)
        ctx.fill(path)
      }
      ctx.globalAlpha = 1
      ctx.strokeStyle = primary
      ctx.lineWidth = 2 / k
      ctx.stroke(selected)

      // Dim what's off-screen, then outline the viewport.
      ctx.globalAlpha = 0.5
      ctx.fillStyle = resolve("--background")
      ctx.beginPath()
      ctx.rect(m.x0, m.y0, width / k, height / k)
      ctx.rect(view.x, view.y, view.w, view.h)
      ctx.fill("evenodd")
      ctx.globalAlpha = 0.7
      ctx.strokeStyle = primary
      ctx.lineWidth = 1.5 / k
      ctx.beginPath()
      ctx.roundRect(view.x, view.y, view.w, view.h, 4 / k)
      ctx.stroke()
      ctx.globalAlpha = 1
    }

    const schedule = () => void (raf ||= requestAnimationFrame(() => draw()))
    const unsubscribe = flow.subscribe(schedule)
    // Theme switches change CSS variables without touching the store.
    const theme = new MutationObserver(() => draw(true))
    theme.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style", "data-theme"] })
    draw(true)
    return () => {
      unsubscribe()
      theme.disconnect()
      cancelAnimationFrame(raf)
    }
  }, [flow, width, height])

  const onPointerDown = (e: PointerEvent<HTMLCanvasElement>) => {
    // Freeze the mapping at drag start so the map doesn't shift under the cursor as bounds change.
    const m = { ...map.current }
    const r = e.currentTarget.getBoundingClientRect()
    const toFlow = (ev: { clientX: number; clientY: number }) => ({ x: m.x0 + (ev.clientX - r.left) / m.k, y: m.y0 + (ev.clientY - r.top) / m.k })
    const s = flow.get()
    const v = s.viewport
    const p = toFlow(e)
    const view = { x: -v.x / v.zoom, y: -v.y / v.zoom, w: s.size.w / v.zoom, h: s.size.h / v.zoom }
    const inside = p.x >= view.x && p.x <= view.x + view.w && p.y >= view.y && p.y <= view.y + view.h
    // Grab the viewport window and drag it; clicking elsewhere centres there first.
    const grab = inside ? { x: p.x - view.x - view.w / 2, y: p.y - view.y - view.h / 2 } : { x: 0, y: 0 }
    const center = (ev: { clientX: number; clientY: number }) => {
      const q = toFlow(ev)
      const { viewport: cur, size } = flow.get()
      flow.setViewport({ ...cur, x: size.w / 2 - (q.x - grab.x) * cur.zoom, y: size.h / 2 - (q.y - grab.y) * cur.zoom })
    }
    center(e)
    drag(center)
  }

  return (
    <div className={cn(PANEL, BOTTOM, "right-4 overflow-hidden", className)}>
      <canvas ref={ref} style={{ width, height }} className="block cursor-grab touch-none active:cursor-grabbing" onPointerDown={onPointerDown} aria-label="Minimap" />
    </div>
  )
}

import { memo, useLayoutEffect, useMemo, useRef, type HTMLAttributes, type KeyboardEvent, type PointerEvent, type ReactNode } from "react"
import { cn } from "@/lib/utils"
import { ConnectionLine, EdgeView } from "./edge"
import { NodeWrapper, ViewContext, type NodeTypes } from "./node"
import { THEME } from "./theme"
import { DEFAULT_SIZE, FlowContext, cancelDrag, drag, shallowArray, useFlow, useFlowState, type ConnectEnd, type Flow, type FlowEdge, type FlowState, type XY } from "./store"

export interface WeaveProps extends Omit<HTMLAttributes<HTMLDivElement>, "onPointerDown"> {
  flow: Flow
  nodeTypes: NodeTypes
  /** Buttons shown on edge hover (or when selected, for touch); defaults to a delete button. */
  edgeToolbar?: (edge: FlowEdge) => ReactNode
  /** A connection drag (or click) on a handle ended away from any compatible handle. */
  onConnectEnd?: (e: ConnectEnd) => void
  fitViewOnInit?: boolean
}

/**
 * Mouse: drag background or scroll to pan, pinch or ⌘/Ctrl+scroll to zoom, Shift-drag to box select.
 * Touch: one finger pans, two fingers pinch/pan, long-press then drag to box select.
 * Keys: Backspace/Delete removes the selection, ⌘A selects all, Esc clears.
 */
export function Weave({ flow, nodeTypes, edgeToolbar, onConnectEnd, fitViewOnInit = true, className, children, onKeyDown, ...rest }: WeaveProps) {
  const ref = useRef<HTMLDivElement>(null)
  const view = useMemo(() => ({ nodeTypes, edgeToolbar }), [nodeTypes, edgeToolbar])

  useLayoutEffect(() => {
    flow.events.onConnectEnd = onConnectEnd
  })

  useLayoutEffect(() => {
    const el = ref.current!
    flow.mount(el)
    const ro = new ResizeObserver(() => flow.set({ size: { w: el.clientWidth, h: el.clientHeight } }))
    ro.observe(el)
    const onWheel = (e: WheelEvent) => {
      e.preventDefault()
      if (e.ctrlKey || e.metaKey) return flow.zoomAt(Math.exp(-e.deltaY * 0.01), e.clientX, e.clientY)
      const v = flow.get().viewport
      flow.setViewport({ ...v, x: v.x - e.deltaX, y: v.y - e.deltaY })
    }
    el.addEventListener("wheel", onWheel, { passive: false })
    // Safari reports trackpad pinch as gesture events (not ctrl+wheel) and would zoom the whole page.
    let gestureZoom = 1
    const onGestureStart = (e: Event) => {
      e.preventDefault()
      gestureZoom = flow.get().viewport.zoom
    }
    const onGestureChange = (e: Event) => {
      e.preventDefault()
      const g = e as Event & { scale: number; clientX: number; clientY: number }
      flow.zoomAt((gestureZoom * g.scale) / flow.get().viewport.zoom, g.clientX, g.clientY)
    }
    el.addEventListener("gesturestart", onGestureStart)
    el.addEventListener("gesturechange", onGestureChange)
    const stopPinch = pinchZoom(el, flow)
    // Two frames: let the first ResizeObserver pass measure nodes before fitting.
    if (fitViewOnInit) requestAnimationFrame(() => requestAnimationFrame(() => flow.fitView(false, 0.4)))
    return () => {
      ro.disconnect()
      el.removeEventListener("wheel", onWheel)
      el.removeEventListener("gesturestart", onGestureStart)
      el.removeEventListener("gesturechange", onGestureChange)
      stopPinch()
      flow.mount(null)
    }
  }, [flow, fitViewOnInit])

  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    if (e.target !== e.currentTarget || e.button > 1) return
    const root = e.currentTarget
    root.focus({ preventScroll: true })
    const r = root.getBoundingClientRect()
    const a = { x: e.clientX - r.left, y: e.clientY - r.top }
    const v0 = flow.get().viewport
    let mode = e.shiftKey && e.button === 0 ? "marquee" : "pan"
    let moved = false
    // Touch has no Shift: hold still briefly, then drag to box select.
    const hold = e.pointerType === "touch" ? setTimeout(() => !moved && ((mode = "marquee"), navigator.vibrate?.(10)), 400) : 0

    drag(
      (ev) => {
        if (!moved && Math.hypot(ev.clientX - e.clientX, ev.clientY - e.clientY) < 4) return
        moved = true
        if (mode === "marquee") return flow.set({ marquee: { a, b: { x: ev.clientX - r.left, y: ev.clientY - r.top } } })
        root.dataset.panning = ""
        flow.setViewport({ ...v0, x: v0.x + ev.clientX - e.clientX, y: v0.y + ev.clientY - e.clientY })
      },
      () => {
        clearTimeout(hold)
        delete root.dataset.panning
        const m = flow.get().marquee
        if (m) {
          flow.selectRect(flow.screenToFlow(m.a), flow.screenToFlow(m.b))
          flow.set({ marquee: null })
        } else if (!moved) flow.select([])
      },
    )
  }

  const keyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(e)
    if (e.defaultPrevented || (e.target as HTMLElement).closest("input,textarea,[contenteditable]")) return
    if (e.key === "Backspace" || e.key === "Delete") flow.removeSelected()
    else if (e.key === "Escape") flow.select([])
    else if ((e.metaKey || e.ctrlKey) && e.key === "a") {
      e.preventDefault()
      flow.select(flow.get().nodeIds)
    }
  }

  return (
    <FlowContext.Provider value={flow}>
      <ViewContext.Provider value={view}>
        <div
          ref={ref}
          tabIndex={0}
          data-weave=""
          {...rest}
          className={cn(
            "relative isolate cursor-grab touch-none overflow-hidden overscroll-none bg-background outline-none select-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-inset [-webkit-tap-highlight-color:transparent] [-webkit-touch-callout:none] data-panning:cursor-grabbing",
            className,
          )}
          onPointerDownCapture={(e) => {
            // A selection made elsewhere would otherwise ride along with every drag.
            const s = getSelection()
            if (s && !s.isCollapsed && !(e.target as Element).closest(EDITABLE)) s.removeAllRanges()
          }}
          // Stop native text selection (multi-click, drag-select) at the source; CSS user-select alone isn't enough in every browser.
          onMouseDown={(e) => !(e.target as Element).closest(EDITABLE) && e.preventDefault()}
          onPointerDown={onPointerDown}
          onKeyDown={keyDown}
        >
          <Background />
          <Transform>
            <Edges />
            <Nodes />
            <ConnectionLine />
          </Transform>
          <Marquee />
          {children}
        </div>
      </ViewContext.Provider>
    </FlowContext.Provider>
  )
}

const EDITABLE = "input,textarea,select,[contenteditable]"

/** Two-finger pinch + pan. Runs in the capture phase so a second finger never starts a node drag. */
function pinchZoom(el: HTMLElement, flow: Flow) {
  const touches = new Map<number, XY>()
  let start: { mid: XY; dist: number; zoom: number; anchor: XY } | null = null
  const local = () => {
    const [p, q] = [...touches.values()]
    const r = el.getBoundingClientRect()
    return { mid: { x: (p.x + q.x) / 2 - r.left, y: (p.y + q.y) / 2 - r.top }, dist: Math.hypot(p.x - q.x, p.y - q.y) || 1 }
  }
  const down = (e: globalThis.PointerEvent) => {
    if (e.pointerType !== "touch") return
    touches.set(e.pointerId, { x: e.clientX, y: e.clientY })
    if (touches.size < 2) return
    e.stopPropagation()
    if (start) return
    cancelDrag()
    delete el.dataset.panning
    flow.set({ connection: null, marquee: null })
    const { mid, dist } = local()
    start = { mid, dist, zoom: flow.get().viewport.zoom, anchor: flow.screenToFlow(mid) }
  }
  const move = (e: globalThis.PointerEvent) => {
    if (!touches.has(e.pointerId)) return
    touches.set(e.pointerId, { x: e.clientX, y: e.clientY })
    if (!start || touches.size < 2) return
    const { mid, dist } = local()
    const zoom = Math.min(2.5, Math.max(0.1, (start.zoom * dist) / start.dist))
    flow.setViewport({ zoom, x: mid.x - start.anchor.x * zoom, y: mid.y - start.anchor.y * zoom })
  }
  const up = (e: globalThis.PointerEvent) => {
    touches.delete(e.pointerId)
    if (touches.size < 2) start = null
  }
  el.addEventListener("pointerdown", down, true)
  addEventListener("pointermove", move)
  addEventListener("pointerup", up)
  addEventListener("pointercancel", up)
  return () => {
    el.removeEventListener("pointerdown", down, true)
    removeEventListener("pointermove", move)
    removeEventListener("pointerup", up)
    removeEventListener("pointercancel", up)
  }
}

/** Runs `apply` on viewport changes, outside React: panning and zooming never re-render anything. */
function useViewportEffect(apply: (v: FlowState["viewport"]) => void) {
  const flow = useFlow()
  useLayoutEffect(() => {
    let last: FlowState["viewport"] | null = null
    const run = () => {
      const v = flow.get().viewport
      if (v !== last) apply((last = v))
    }
    run()
    return flow.subscribe(run)
  }, [flow, apply])
}

function Transform({ children }: { children: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null)
  useViewportEffect(
    useMemo(() => (v) => void (ref.current!.style.transform = `translate(${v.x}px,${v.y}px) scale(${v.zoom})`), []),
  )
  return (
    <div ref={ref} className="absolute top-0 left-0 origin-top-left">
      {children}
    </div>
  )
}

function Background() {
  const ref = useRef<HTMLDivElement>(null)
  useViewportEffect(
    useMemo(
      () => (v) => {
        const gap = 20 * v.zoom
        const s = ref.current!.style
        s.backgroundImage = gap < 7 ? "none" : `radial-gradient(circle, ${THEME.dot} 1px, transparent 1.25px)`
        s.backgroundSize = `${gap}px ${gap}px`
        s.backgroundPosition = `${v.x - gap / 2}px ${v.y - gap / 2}px`
      },
      [],
    ),
  )
  return <div ref={ref} className="pointer-events-none absolute inset-0" />
}

// ---- viewport culling: only nodes/edges near the screen are mounted ----

const MARGIN = 240 // screen px kept mounted beyond each edge, so fast pans don't show pop-in

function viewRect(s: FlowState) {
  const { x, y, zoom } = s.viewport
  return { x0: (-x - MARGIN) / zoom, y0: (-y - MARGIN) / zoom, x1: (s.size.w - x + MARGIN) / zoom, y1: (s.size.h - y + MARGIN) / zoom }
}

function visibleNodeIds(s: FlowState) {
  if (!s.size.w) return s.nodeIds
  const v = viewRect(s)
  return s.nodeIds.filter((id) => {
    const n = s.nodes[id]
    const z = s.sizes[id] ?? DEFAULT_SIZE
    // Selected nodes stay mounted so dragging one off-screen keeps its state.
    return n.selected || (n.position.x < v.x1 && n.position.x + z.w > v.x0 && n.position.y < v.y1 && n.position.y + z.h > v.y0)
  })
}

function visibleEdges(s: FlowState) {
  if (!s.size.w) return s.edges
  const v = viewRect(s)
  return s.edges.filter((e) => {
    const a = s.nodes[e.source], b = s.nodes[e.target]
    if (!a || !b) return false
    const za = s.sizes[e.source] ?? DEFAULT_SIZE, zb = s.sizes[e.target] ?? DEFAULT_SIZE
    // Bounding box of both endpoint nodes, padded for bezier overshoot.
    const pad = 120
    const x0 = Math.min(a.position.x, b.position.x) - pad, x1 = Math.max(a.position.x + za.w, b.position.x + zb.w) + pad
    const y0 = Math.min(a.position.y, b.position.y) - pad, y1 = Math.max(a.position.y + za.h, b.position.y + zb.h) + pad
    return x0 < v.x1 && x1 > v.x0 && y0 < v.y1 && y1 > v.y0
  })
}

const Nodes = memo(function Nodes() {
  const ids = useFlowState(visibleNodeIds, shallowArray)
  return ids.map((id) => <NodeWrapper key={id} id={id} />)
})

const Edges = memo(function Edges() {
  const edges = useFlowState(visibleEdges, shallowArray)
  return edges.map((e) => <EdgeView key={e.id} edge={e} />)
})

function Marquee() {
  const m = useFlowState((s) => s.marquee)
  if (!m) return null
  return (
    <div
      className="pointer-events-none absolute rounded-sm border border-primary/50 bg-primary/8"
      style={{ left: Math.min(m.a.x, m.b.x), top: Math.min(m.a.y, m.b.y), width: Math.abs(m.a.x - m.b.x), height: Math.abs(m.a.y - m.b.y) }}
    />
  )
}

/**
 * Weave's themable colours. Everything else uses shadcn tokens directly (card, border, primary, ring…).
 *
 * Set any `--weave-*` variable on `:root`, a theme class, or a single canvas to override it. Defaults
 * are resolved where they're used (not declared on :root), so a nested shadcn theme recolours Weave too.
 */
export const THEME = {
  /** Background dot grid. */
  dot: "var(--weave-dot, color-mix(in oklch, var(--muted-foreground) 35%, transparent))",
  /** Resting connection. */
  edge: "var(--weave-edge, color-mix(in oklch, var(--muted-foreground) 45%, transparent))",
  /** Hovered connection. */
  edgeHover: "var(--weave-edge-hover, color-mix(in oklch, var(--foreground) 70%, transparent))",
  /** Selected connection and the line drawn while connecting. */
  edgeSelected: "var(--weave-edge-selected, var(--primary))",
  /** Animated (`edge.animated`) connection. */
  edgeFlow: "var(--weave-edge-flow, var(--primary))",
}
// Also: --weave-handle (port outline) is applied as a class in node.tsx, defaulting to muted-foreground at 60%.
